    /// <summary>
    /// Initialize the form for DaxWalkmeParaemters
    /// </summary>
    public void init()
    {        
        
        super();
        //Fetch the table buffer to check if it is enable
        DAXVWalkMeParameters DAXVWalkMeParameters = DAXVWalkMeParameters::find();
          
        //Daxwalkmeparameter is enable for injecting the javascript code
        if (DAXVWalkMeParameters.IsEnabled)
        {
            str env = '' ; // variable to get the environment details

            if(DAXVWalkMeParameters.CustomEnvironment && DAXVWalkMeParameters.DAXVGUID )
            {
                env = "/" + DAXVWalkMeParameters.CustomEnvironment; // Custom environment we need to assign
            }
            else if(DAXVWalkMeParameters.IsTestEnvironment)
            {
                env = "/test"; // for sandbox we are assigning
            }
            else
            {
                env = ""; // for produciton we are assinging.
            }

            //Concatinating the Environment name with  Guid and environment name
            str url = "https://cdn.walkme.com/users/" + DAXVWalkMeParameters.DAXVGUID + env + "/walkme_" +  DAXVWalkMeParameters.DAXVGUID + "_https.js";


            DAXVWalkMeControl1.parmURL(url); // Assign the url to control Parameter.

        }
    }
